const CROCODILE_FLAT: Array<{ word: string; category: string }> = Object.entries(CROCODILE_CATEGORIES).flatMap(
  ([category, words]) => words.map((word) => ({ word, category })),
);

export function randomCrocodileWord(exclude: string[] = []) {
  const excludeSet = new Set(exclude.map((w) => w.toLowerCase()));
  const pool = CROCODILE_FLAT.filter((e) => !excludeSet.has(e.word));
  const source = pool.length ? pool : CROCODILE_FLAT;
  const pick = source[Math.floor(Math.random() * source.length)];
  return { word: pick.word, category: pick.category };
}

export function containsWord(text: string, word: string): boolean {
  if (!text?.trim() || !word?.trim()) return false;
  const escaped = word.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const re = new RegExp(`(^|\\W)${escaped}(\\W|$)`, "iu");
  return re.test(text);
}
